function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Invalid CSRF token');}}
function me():?array{return $_SESSION['user']??null;}
function login():array{if(!me()){header('Location:?page=login');exit;}return me();}
function admin():array{$u=login();if($u['role']!=='super_admin'){http_response_code(403);exit('Forbidden');}return $u;}
function audit(PDO $db,int $uid,string $action,string $type='',int $rid=0,string $details=''):void{$q=$db->prepare('INSERT INTO audit_logs(user_id,action,resource_type,resource_id,details,ip_address) VALUES(?,?,?,?,?,?)');$q->execute([$uid,$action,$type?:null,$rid?:null,$details,$_SERVER['REMOTE_ADDR']??'']);}
function cryptval(string $v):string{return base64_encode($v);}function decryptval(string $v):string{return base64_decode($v,true)?:'';}
function permitted(PDO $db,array $u,string $type,int $id,bool $manage=false):bool{if($u['role']==='super_admin')return true;$col=$manage?'can_manage':'can_view';$q=$db->prepare("SELECT 1 FROM resource_permissions WHERE reseller_id=? AND resource_type=? AND resource_id=? AND can_view=1 AND {$col}=1");$q->execute([$u['id'],$type,$id]);return(bool)$q->fetchColumn();}
final class ROS{private $s;private array $r;function __construct(array $r){$this->r=$r;}private function len(int $n):string{if($n<128)return chr($n);if($n<16384)return chr(($n>>8)|128).chr($n&255);if($n<2097152)return chr(($n>>16)|192).chr(($n>>8)&255).chr($n&255);if($n<268435456)return chr(($n>>24)|224).chr(($n>>16)&255).chr(($n>>8)&255).chr($n&255);return chr(240).pack('N',$n);}private function sw(string $w):void{fwrite($this->s,$this->len(strlen($w)).$w);}private function send(array $a):void{foreach($a as $w)$this->sw($w);fwrite($this->s,"\0");}private function rw():?string{$c=fread($this->s,1);if($c===false||$c==='')return null;$n=ord($c);if($n<128)$l=$n;elseif(($n&224)===192)$l=(($n&31)<<8)|ord(fread($this->s,1));elseif(($n&240)===224)$l=(($n&15)<<16)|(ord(fread($this->s,1))<<8)|ord(fread($this->s,1));elseif(($n&248)===240)$l=(($n&7)<<24)|(ord(fread($this->s,1))<<16)|(ord(fread($this->s,1))<<8)|ord(fread($this->s,1));else{$l=unpack('N',fread($this->s,4))[1];}$v='';while(strlen($v)<$l){$x=fread($this->s,$l-strlen($v));if($x===false||$x==='')break;$v.=$x;}return$v;}private function sentence():array{$type='';$o=[];while(true){$w=$this->rw();if($w===null||$w==='')break;if($w[0]==='!'){$type=$w;$o[$type]=[];}elseif($type)$o[$type][]=$w;}return$o;}private function connect():void{$this->s=@fsockopen($this->r['host'],(int)$this->r['api_port'],$no,$msg,8);if(!$this->s)throw new RuntimeException('RouterOS connection failed: '.$msg);stream_set_timeout($this->s,8);$this->send(['/login','=name='.$this->r['username'],'=password='.decryptval($this->r['password_enc'])]);$x=$this->sentence();if(isset($x['!trap']))throw new RuntimeException('RouterOS login failed');}function call(string $cmd,array $args=[]):array{$this->connect();$w=[$cmd];foreach($args as $k=>$v)$w[]='='.$k.'='.$v;$this->send($w);$rows=[];while(true){$x=$this->sentence();if(isset($x['!trap'])){fclose($this->s);throw new RuntimeException('RouterOS command failed');}if(isset($x['!re']))$rows[]=$x['!re'];if(isset($x['!done']))break;}fclose($this->s);$out=[];foreach($rows as $row){$a=[];foreach($row as $w){if($w[0]==='='){[$k,$v]=array_pad(explode('=',substr($w,1),2),2,'');$a[$k]=$v;}}$out[]=$a;}return$out;}}
function get_router(PDO $db,int $id):array{$q=$db->prepare('SELECT * FROM mikrotiks WHERE id=? AND active=1');$q->execute([$id]);$r=$q->fetch();if(!$r)throw new RuntimeException('Router not found');return$r;}function get_olt(PDO $db,int $id):array{$q=$db->prepare('SELECT * FROM olts WHERE id=? AND active=1');$q->execute([$id]);$o=$q->fetch();if(!$o)throw new RuntimeException('OLT not found');return$o;}
function olt_exec(array $o,string $command):string{$command=trim($command);if($command==='')throw new RuntimeException('OLT command is not configured.');$host=preg_replace('/[^A-Za-z0-9.:-]/','',$o['host']);$usr=preg_replace('/[^A-Za-z0-9_.-]/','',$o['username']);$ask=tempnam(sys_get_temp_dir(),'ask');file_put_contents($ask,"#!/bin/sh\nprintf '%s\\n' ".escapeshellarg(decryptval($o['password_enc'])));chmod($ask,0700);putenv('SSH_ASKPASS='.$ask);putenv('SSH_ASKPASS_REQUIRE=force');putenv('DISPLAY=:0');$cmd='setsid ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=8 -p '.escapeshellarg((string)$o['port']).' '.escapeshellarg($usr.'@'.$host).' '.escapeshellarg($command).' 2>&1';$out=shell_exec($cmd);@unlink($ask);putenv('SSH_ASKPASS');putenv('SSH_ASKPASS_REQUIRE');return trim((string)$out);}
