dy"><div class="row"><?php foreach(['name'=>'Name','host'=>'IP/Host','port'=>'SSH Port','username'=>'SSH Username','password'=>'SSH Password','vendor'=>'Vendor'] as $n=>$lab):?><div class="col-md-6"><label><?=$lab?></label><input class="form-control mb-2" name="<?=$n?>" value="<?=$n==='port'?'22':($n==='vendor'?'ECOM':'')?>" required></div><?php endforeach;?></div><div class="alert alert-info small">ECOM CLI differs by model/firmware. Enter supported commands for status, ONU/laser and reboot. Outbound SSH/OpenSSH must be available on the hosting server.</div><?php foreach(['status_command'=>'Status command','onu_command'=>'ONU / laser command','reboot_command'=>'ONU reboot command'] as $n=>$lab):?><label><?=$lab?></label><textarea class="form-control mb-2" name="<?=$n?>"></textarea><?php endforeach;?></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><?php endif;
}elseif($page==='resellers'&&$u['role']==='super_admin'){$rs=$db->query("SELECT * FROM users WHERE role='reseller' ORDER BY id DESC")->fetchAll();?><div class="d-flex justify-content-between"><h2>Resellers</h2><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#resAdd">Add Reseller</button></div><table class="table bg-white mt-3"><tr><th>Username</th><th>Name</th><th>Status</th></tr><?php foreach($rs as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['full_name'])?></td><td><?=!empty($r['active'])?'Active':'Disabled'?></td></tr><?php endforeach;?></table><div class="modal fade" id="resAdd"><div class="modal-dialog"><form method="post" class="modal-content"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="reseller_add"><input type="hidden" name="return" value="resellers"><div class="modal-body"><input class="form-control mb-2" name="username" placeholder="Username" required><input class="form-control mb-2" name="full_name" placeholder="Name"><input class="form-control" type="password" name="password" placeholder="Password 8+ chars" required></div><div class="modal-footer"><button class="btn btn-primary">Create</button></div></form></div></div><?php
}elseif($page==='permissions'&&$u['role']==='super_admin'){$rs=$db->query("SELECT id,username FROM users WHERE role='reseller' AND active=1")->fetchAll();$ps=$db->query('SELECT * FROM resource_permissions ORDER BY id DESC')->fetchAll();?><h2>Permissions</h2><div class="card p-3"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="permission"><input type="hidden" name="return" value="permissions"><div class="col-md-3"><select class="form-select" name="reseller_id"><?php foreach($rs as $r):?><option value="<?=$r['id']?>"><?=e($r['username'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="resource_type"><option value="mikrotik">MikroTik</option><option value="olt">OLT</option></select></div><div class="col-md-3"><input class="form-control" name="resource_id" placeholder="Resource ID" required></div><div class="col-md-2"><label><input type="checkbox" name="can_view" checked> View</label> <label><input type="checkbox" name="can_manage"> Manage</label></div><div class="col-md-2"><button class="btn btn-primary">Save</button></div></form></div><table class="table bg-white mt-3"><tr><th>Reseller</th><th>Type</th><th>Resource</th><th>View</th><th>Manage</th></tr><?php foreach($ps as $p):?><tr><td><?=e($p['reseller_id'])?></td><td><?=e($p['resource_type'])?></td><td><?=e($p['resource_id'])?></td><td><?=!empty($p['can_view'])?'Yes':'No'?></td><td><?=!empty($p['can_manage'])?'Yes':'No'?></td></tr><?php endforeach;?></table><?php
}elseif($page==='audit'&&$u['role']==='super_admin'){$logs=$db->query('SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetchAll();?><h2>Audit Log</h2><div class="table-responsive"><table class="table table-sm bg-white"><tr><th>Time</th><th>User</th><th>Action</th><th>Resource</th><th>Details</th><th>IP</th></tr><?php foreach($logs as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e($l['username'])?></td><td><?=e($l['action'])?></td><td><?=e($l['resource_type'].'#'.$l['resource_id'])?></td><td><?=e($l['details'])?></td><td><?=e($l['ip_address'])?></td></tr><?php endforeach;?></table></div><?php }else{echo '<div class="alert alert-warning">Page not found.</div>';}?></main></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
